{
  "want": "ユーザー登録とログインができて、ログイン後にダッシュボードで自分の利用状況を見られる小規模 Web アプリを作りたい。登録完了時と重要な変更時には通知メールを送りたい。運営者向けには全ユーザーの利用状況を集計したレポート画面もほしい。",
  "granularity": "feature",
  "dependency_policy": "explicit_inter_feature_depends_on",
  "features": [
    {
      "id": "feat-user-auth",
      "title": "ユーザー登録・ログイン機能",
      "purpose": "ユーザーが自分のアカウントを作成し安全にログインできるようにする",
      "depends_on": []
    },
    {
      "id": "feat-user-dashboard",
      "title": "ユーザーダッシュボード",
      "purpose": "ログイン済みユーザーが自分の利用状況を確認できるようにする",
      "depends_on": ["feat-user-auth"]
    },
    {
      "id": "feat-email-notification",
      "title": "通知メール送信",
      "purpose": "登録完了時と重要な変更時にメールで通知する",
      "depends_on": ["feat-user-auth"]
    },
    {
      "id": "feat-admin-report",
      "title": "運営者向けレポート画面",
      "purpose": "運営者が全ユーザーの利用状況を集計して確認できるようにする",
      "depends_on": ["feat-user-auth", "feat-user-dashboard"]
