  "architecture": [
    {
      "id": "arch-web-app-stack",
      "title": "小規模Webアプリ技術スタック",
      "subtypes": ["backend", "frontend", "data"]
    }
  ]
}
EOF

# Compute its digest
BRIEF_DIGEST=$(python3 -c "import hashlib; print(hashlib.sha256(open('$DEV_GRAPH_ROOT/eval-log/macro-decomposition-brief.json','rb').read()).hexdigest())")
echo "Brief digest: $BRIEF_DIGEST"

